#!/usr/bin/env bash
# loopd.sh (pilot-repo edition) — GENERATED by `chug loop run` (T334).
#
# Runs LOOP-SPEC cycles back-to-back against THIS repo's own queue:
# TODO.md is the queue, LOOP-SPEC.md the contract, .chug/loopd/ the state.
# Worktrees live under this repo; commits land on this repo's branches.
#
# Regenerated on every `chug loop run` — operator edits to THIS file are
# overwritten; point CHUG_LOOPD_BIN at your own supervisor script to opt
# out (it must keep the loader fragments beside it, same as loopd.sh).
#
#   <this script> run      the supervisor loop (default)
#   <this script> stop     exit after the current cycle
#   <this script> status   liveness + recent activity
#
# Environment resolution is the installed loopd's (T205 + T330 + T332):
# the SAME loader fragments chug's own supervisor sources are written
# beside this script and sourced here — $HOME/.chug/profile.env lands
# ANTHROPIC_*/model env exactly as the chug repo's loopd gets it, explicit
# env wins everywhere, and an absent file is a silent no-op. The file
# CONTENTS are never logged (the T205 hygiene gate) — only paths and
# skipped-line counts.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"
STATE=.chug/loopd
mkdir -p "$STATE"
PIDFILE=$STATE/loopd.pid
LOG=$STATE/loopd.log
STOP=.chug/STOP-LOOP

ts() { date -u +%Y-%m-%dT%H:%M:%SZ; }

# T205 — the judge env file, loaded ONCE at startup (the T47 lesson: no
# env mutation inside the cycle loop; a token rotation is edit + restart).
LOOPD_ENV_FILE="${CHUG_LOOPD_ENV:-$HOME/.chug/loopd.env}"
. "$(dirname "$0")/scripts/loopd_env_loader.sh"
loopd_load_env_file

# T330 — the LLM profile, loaded ONCE at startup (the T47 lesson).
PROFILE_ENV_FILE="${CHUG_PROFILE_ENV:-$HOME/.chug/profile.env}"
. "$(dirname "$0")/scripts/loopd_profile_loader.sh"
loopd_load_profile

# The cycle's model. The profile (loaded above) lands CHUG_MODEL_CODING on
# LOOP_ROUTINE_MODEL — the pilot loop's workhorse lane (queue work is
# coding work) — and CHUG_MODEL_REASONING on LOOP_ORCH_MODEL. Precedence:
# routine, then orchestrator, then today's default full id. Model ids go
# VERBATIM into the API request body (there is no alias layer) — never a
# bare shorthand. ROLLBACK: one env var pins the model —
#   LOOP_ROUTINE_MODEL=<full id> ./run
CHUG_LOOP_MODEL="${LOOP_ROUTINE_MODEL:-${LOOP_ORCH_MODEL:-anthropic-system.ai.kimi-k3}}"

# The chug binary the cycles launch: `chug loop run` exports
# CHUG_LOOP_BIN=<its own executable> at exec time (the installed binary —
# no clone of chug is ever built or required); a bare `chug` on PATH is
# the fallback when the supervisor is started by hand.
CHUG_BIN="${CHUG_LOOP_BIN:-}"
if [ -z "$CHUG_BIN" ]; then
  CHUG_BIN="$(command -v chug || true)"
fi
if [ -z "$CHUG_BIN" ]; then
  echo "chug binary not found (set CHUG_LOOP_BIN or put chug on PATH)" >&2
  exit 1
fi

# Cycle budgets (the `chug run` defaults; env-overridable) and pacing.
MAX_ITERS="${LOOPD_MAX_ITERS:-40}"
MAX_MINUTES="${LOOPD_MAX_MINUTES:-120}"
SLEEP_OK="${LOOPD_SLEEP_OK:-60}"
SLEEP_EMPTY="${LOOPD_EMPTY_SLEEP:-300}"
SLEEP_FAIL="${LOOPD_SLEEP_FAIL:-300}"

# T47 — the shared worktree build cache (children + gates build into ONE
# dir, never the repo's own target/). Inert on a non-Rust repo. Keep the
# loop's own dirt out of the queue repo's git status (best-effort: an
# untracked build cache would pollute every delta the loop reads).
mkdir -p target-shared
for ign in .chug/ target-shared/; do
  if [ -f .gitignore ] && grep -qx "$ign" .gitignore 2>/dev/null; then
    :
  elif [ -f .gitignore ]; then
    printf '%s\n' "$ign" >> .gitignore || true
  else
    printf '%s\n' "$ign" > .gitignore || true
  fi
done

# The queue's open-row count: TODO.md data rows (T or P ids — the T326
# Proposed lane's rows are real work once the operator flips them open)
# whose status cell is `todo` or `open`. The empty-queue gate below is
# what keeps a fresh scaffold from manufacturing work.
open_rows() {
  [ -f TODO.md ] || { echo 0; return; }
  awk -F'|' '/^[|]/ {
    id=$2; gsub(/[ \t]/, "", id)
    if (id ~ /^[TP][0-9]+$/) { s=$6; gsub(/[ \t]/, "", s); if (s == "todo" || s == "open") n++ }
  } END { print n + 0 }' TODO.md
}

case "${1:-run}" in
  stop)
    touch "$STOP"
    echo "stop requested — supervisor exits after the current cycle"
    exit 0
    ;;
  status)
    if [ -f "$PIDFILE" ] && kill -0 "$(cat "$PIDFILE")" 2>/dev/null; then
      echo "loopd RUNNING (pid $(cat "$PIDFILE"))"
    else
      echo "loopd NOT running"
    fi
    # A report, not a gate — every leg degrades to "nothing to report"
    # and must never trip set -e (the T137 house style).
    [ -f "$STATE/HALTED" ] && echo "HALTED: $(cat "$STATE/HALTED")" || true
    echo "--- recent:"
    tail -5 "$LOG" 2>/dev/null || true
    exit 0
    ;;
  run) ;;
  *) echo "usage: loopd.sh [run|stop|status]" >&2; exit 2 ;;
esac

# Single instance (the loopd.sh T50 shape): refuse a LIVE foreign
# supervisor; a stale (dead) pid keeps the fall-through.
if [ -f "$PIDFILE" ] && [ "$(cat "$PIDFILE")" != "$$" ] \
   && kill -0 "$(cat "$PIDFILE")" 2>/dev/null; then
  echo "loopd already running (pid $(cat "$PIDFILE"))" >&2
  exit 1
fi
echo $$ > "$PIDFILE"
rm -f "$STOP" "$STATE/HALTED"
trap 'rm -f "$PIDFILE"' EXIT

echo "$(ts) loopd start (pid $$) — $(open_rows) open row(s), model $CHUG_LOOP_MODEL, binary $CHUG_BIN" >> "$LOG"

fails=0
while [ ! -f "$STOP" ]; do
  # Single-driver: never overlap another LOOP-SPEC run. The listing is
  # CAPTURED, then grepped — never a ps-to-grep pipeline (the T137 shape:
  # under pipefail a SIGPIPE'd writer leg would flip a LIVE driver to
  # "no driver" and a duplicate would launch).
  ps_rc=0
  ps_out="$(ps -ax -o command=)" || ps_rc=$?
  if [ "$ps_rc" -ne 0 ]; then
    echo "$(ts) driver probe FAILED (ps rc=$ps_rc) — enumeration unknown; refusing to risk a duplicate driver, skipping" >> "$LOG"
    sleep 120
    continue
  fi
  if grep -q "[c]hug run --spec LOOP-SPEC.md" <<<"$ps_out"; then
    echo "$(ts) another LOOP-SPEC driver active; skipping" >> "$LOG"
    sleep 120
    continue
  fi
  # The empty-queue gate: no open rows, no launch — the loop idles instead
  # of manufacturing work (the adoption flaw T334 exists to kill: a pilot's
  # first experience must be their OWN queue worked, never a made-up one).
  rows=$(open_rows)
  if [ "$rows" -eq 0 ]; then
    echo "$(ts) queue empty (0 open rows) — dormant, re-probing in ${SLEEP_EMPTY}s" >> "$LOG"
    sleep "$SLEEP_EMPTY"
    continue
  fi
  cycle_log="$STATE/cycle-$(date -u +%Y%m%d-%H%M%S).log"
  echo "$(ts) cycle start -> $cycle_log ($rows open row(s), orchestrator $CHUG_LOOP_MODEL)" >> "$LOG"
  echo "[loopd $(ts)] $rows open row(s), orchestrator $CHUG_LOOP_MODEL" > "$cycle_log"
  # T142: the verdict is the child's EXIT STATUS, never a log grep. The
  # stdout capture is kept apart from the mixed stderr log and appended
  # back, the rc latched (the T142 house style) — a model-forged
  # "chug: goal complete" line can neither flip the verdict nor mask a
  # death. The launch env carries the T47 shared cache as a per-invocation
  # prefix (NEVER a bare export — it would persist across iterations and
  # poison the supervisor's own resolution).
  chug_rc=0
  chug_out="$(CARGO_TARGET_DIR="$ROOT/target-shared" "$CHUG_BIN" run --spec LOOP-SPEC.md \
    --goal "Work this repo's queue per LOOP-SPEC.md: take the highest-priority open TODO.md row, land its spec green (the check: contract and the gates, commits on this repo's branches), then wrap the bookkeeping — TODO.md statuses and the ledger — so a cold next cycle needs zero human words. Never invent work: proposals go only to the Proposed lane and wait for the operator." \
    --model "$CHUG_LOOP_MODEL" --max-iters "$MAX_ITERS" --max-minutes "$MAX_MINUTES" \
    2>> "$cycle_log")" || chug_rc=$?
  printf '%s\n' "$chug_out" >> "$cycle_log"
  if [ "$chug_rc" -eq 0 ]; then
    echo "[loopd $(ts)] verdict: goal complete (rc=$chug_rc)" >> "$cycle_log"
  else
    echo "[loopd $(ts)] verdict: no goal complete (rc=$chug_rc)" >> "$cycle_log"
  fi
  if [ "$chug_rc" -eq 0 ]; then
    fails=0
    echo "$(ts) cycle OK" >> "$LOG"
    sleep "$SLEEP_OK"
  else
    fails=$((fails + 1))
    echo "$(ts) cycle ended WITHOUT goal complete (consecutive failures: $fails)" >> "$LOG"
    if [ "$fails" -ge 3 ]; then
      echo "3 consecutive cycles without goal_complete — last: $cycle_log" > "$STATE/HALTED"
      echo "$(ts) HALTED after 3 consecutive failures" >> "$LOG"
      exit 1
    fi
    sleep "$SLEEP_FAIL"
  fi
done
echo "$(ts) stop file present — clean exit" >> "$LOG"
